package com.findit.servlet;
import com.findit.dao.ItemDAO;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.SQLException;
@WebServlet("/resolve") public class ResolveServlet extends HttpServlet {protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.sendRedirect(q.getContextPath()+"/login");return;}try{boolean admin="ADMIN".equals(s.getAttribute("role"));new ItemDAO().resolve(Integer.parseInt(q.getParameter("itemId")),((Number)s.getAttribute("userId")).intValue(),admin);p.sendRedirect(q.getContextPath()+"/my-items");}catch(SQLException|NumberFormatException e){throw new ServletException(e);}}}
